 public IndexedPriorityQueue(){super(DataStructuresNative.INSTANCE.coolbox_ds_indexed_queue_new(),DataStructuresNative.INSTANCE::coolbox_ds_indexed_queue_free);}
 public void push(long key,double priority){DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_indexed_queue_push(handle(),key,priority));} public void update(long key,double priority){DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_indexed_queue_update(handle(),key,priority));} public PriorityEntry top(){LongByReference k=new LongByReference();DoubleByReference p=new DoubleByReference();if(DataStructuresNative.INSTANCE.coolbox_ds_indexed_queue_top(handle(),k,p)==0)throw new CoolBoxException("priority queue is empty");return new PriorityEntry(k.getValue(),p.getValue());} public PriorityEntry pop(){PriorityEntry item=top();DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_indexed_queue_pop(handle()));return item;} public boolean contains(long key){return DataStructuresNative.INSTANCE.coolbox_ds_indexed_queue_contains(handle(),key)!=0;} public long size(){return DataStructuresNative.INSTANCE.coolbox_ds_indexed_queue_size(handle());} public boolean isEmpty(){return DataStructuresNative.INSTANCE.coolbox_ds_indexed_queue_empty(handle())!=0;} public void clear(){DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_indexed_queue_clear(handle()));}
